import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        long[] p = new long[n];
        for (int i = 0; i < n; i++) { st.nextToken(); p[i] = (long) st.nval; }
        // dp[i] = best score using only indices i..n-1; taking i blocks i+1..i+p[i].
        long[] dp = new long[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            int nxt = (int) Math.min(n, i + p[i] + 1);
            dp[i] = Math.max(dp[i + 1], p[i] + dp[nxt]);
        }
        System.out.println(dp[0]);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n := nextInt()
	p := make([]int, n)
	for i := range p {
		p[i] = nextInt()
	}
	// dp[i] = best score using only indices i..n-1; taking i blocks i+1..i+p[i].
	dp := make([]int, n+1)
	for i := n - 1; i >= 0; i-- {
		nxt := min(n, i+p[i]+1)
		dp[i] = max(dp[i+1], p[i]+dp[nxt])
	}
	fmt.Println(dp[0])
}
